package hu.synostream.android;
import android.content.*;import android.content.pm.*;import android.net.Uri;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.*;
@RunWith(AndroidJUnit4.class) public class Android054Test {
 final Android050FlowTest f=new Android050FlowTest();
 @After public void cleanup()throws Exception{if(f.app!=null)f.instrumentation.runOnMainSync(()->{f.app.cancelScan();f.app.epoch++;f.app.torrentDraft.close();f.app.externalTorrentUri=null;f.app.externalTorrentMime=null;});f.cleanup();}
 void setup(FakeNas n)throws Exception{f.setup(n,List.of());f.instrumentation.waitForIdleSync();f.instrumentation.runOnMainSync(()->{f.app.torrentDraft.close();f.app.externalTorrentUri=null;});}
 void send(String kind,boolean share){f.context.startActivity(new Intent().setComponent(new ComponentName(f.pkg+".test","hu.synostream.android.FixtureTorrentSender")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("kind",kind).putExtra("share",share));}
 void filename(String name)throws Exception{long end=System.currentTimeMillis()+10000;while(!name.equals(f.app.torrentDraft.filename)&&System.currentTimeMillis()<end)Thread.sleep(50);assertEquals(name,f.app.torrentDraft.filename);assertNotNull(f.app.torrentDraft.bytes);}
 void input(String id,String value)throws Exception{String resource=f.pkg+":id/"+id;if(!f.device.wait(Until.hasObject(By.res(resource)),5000))new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().resourceId(resource));assertTrue("Login field after rotation: "+id,f.device.wait(Until.hasObject(By.res(resource)),10000));f.device.findObject(By.res(resource)).setText(value);}
 @Test public void filtersAcceptViewAndShareButNotDocuments()throws Exception{try(FakeNas n=new FakeNas()){setup(n);PackageManager pm=f.context.getPackageManager();for(String type:List.of("application/x-bittorrent","application/x-torrent","application/octet-stream"))for(String action:List.of(Intent.ACTION_VIEW,Intent.ACTION_SEND)){Intent i=new Intent(action);if(action.equals(Intent.ACTION_VIEW))i.setDataAndType(Uri.parse("content://fixture/document/opaque"),type);else i.setType(type);assertTrue(pm.queryIntentActivities(i,PackageManager.MATCH_DEFAULT_ONLY).stream().anyMatch(r->f.pkg.equals(r.activityInfo.packageName)));}for(String type:List.of("image/jpeg","application/pdf"))assertFalse(pm.queryIntentActivities(new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("content://fixture/document/opaque"),type),PackageManager.MATCH_DEFAULT_ONLY).stream().anyMatch(r->f.pkg.equals(r.activityInfo.packageName)));assertEquals(ActivityInfo.LAUNCH_SINGLE_TASK,pm.getActivityInfo(new ComponentName(f.context,MainActivity.class),0).launchMode);}}
 @Test public void externalViewReadsGrantedUriAndWaitsForFileConfirmation()throws Exception{try(FakeNas n=new FakeNas()){setup(n);MainActivity before=f.activity();send("ok",false);filename("Example.torrent");assertSame(before,f.activity());assertEquals(0,n.prepares);assertEquals(0,n.starts);assertTrue(f.device.takeScreenshot(new java.io.File(f.context.getFilesDir(),"054-torrent-import.png")));f.text("Hozzáadás");assertTrue(f.device.wait(Until.hasObject(By.text("release.nfo")),15000));assertTrue(f.device.findObject(By.text("release.nfo")).isChecked());assertFalse(f.device.findObject(By.text("Sample/clip.mkv")).isChecked());assertEquals(0,n.starts);}}
 @Test public void sharedNamelessTorrentGetsSafeName()throws Exception{try(FakeNas n=new FakeNas()){setup(n);send("nameless",true);filename("Megnyitott torrent.torrent");assertEquals(0,n.prepares);assertEquals(0,n.starts);}}
 @Test public void existingDraftNeedsConfirmationBeforeReplacement()throws Exception{try(FakeNas n=new FakeNas()){setup(n);send("ok",false);filename("Example.torrent");send("second",false);assertTrue(f.device.wait(Until.hasObject(By.text("Új torrentfájl")),10000));f.device.findObject(By.res("android:id/button2")).click();assertEquals("Example.torrent",f.app.torrentDraft.filename);send("second",false);assertTrue(f.device.wait(Until.hasObject(By.text("Új torrentfájl")),10000));f.device.findObject(By.res("android:id/button1")).click();filename("Second.torrent");assertEquals(0,n.prepares);}}
 @Test public void busyImportIsDeferred()throws Exception{try(FakeNas n=new FakeNas()){setup(n);f.instrumentation.runOnMainSync(()->f.app.downloadBusy=true);send("ok",false);Thread.sleep(900);assertFalse(f.app.torrentDraft.open);assertNotNull(f.app.externalTorrentUri);f.instrumentation.runOnMainSync(()->f.app.downloadBusy=false);filename("Example.torrent");assertEquals(0,n.prepares);}}
 @Test public void wrongBinaryAndUnreadableTorrentNeverUpload()throws Exception{try(FakeNas n=new FakeNas()){setup(n);send("wrong",false);Thread.sleep(1500);assertNull(f.app.torrentDraft.bytes);f.instrumentation.runOnMainSync(()->f.app.torrentDraft.close());send("missing",false);Thread.sleep(1500);assertNull(f.app.torrentDraft.bytes);assertEquals(0,n.prepares);assertEquals(0,n.starts);}}
 @Test public void pendingImportSurvivesLoggedOutRotation()throws Exception{try(FakeNas n=new FakeNas()){setup(n);f.instrumentation.runOnMainSync(()->{f.app.client=null;f.app.changed();});send("ok",false);long pendingEnd=System.currentTimeMillis()+7000;while(f.app.externalTorrentUri==null&&System.currentTimeMillis()<pendingEnd)Thread.sleep(50);assertNotNull("Incoming URI before rotation",f.app.externalTorrentUri);f.device.setOrientationLeft();Thread.sleep(900);assertNotNull("Incoming URI after rotation",f.app.externalTorrentUri);f.device.setOrientationNatural();Thread.sleep(600);input("login_address",n.address());input("login_user","fixture-user");input("login_password","fixture-password");f.click("login_button");filename("Example.torrent");assertEquals(0,n.prepares);}}
 @Test public void multilingualPlaybackHandsUnrestrictedViewIntentToAndroid()throws Exception{try(FakeNas n=new FakeNas()){String path="/Movies/Multilingual.mkv";n.files.put(path,Android050FlowTest.join(new byte[]{0x18,0x53,(byte)0x80,0x67,(byte)0xff},Android050FlowTest.elem(0x1654ae6b,Android050FlowTest.join(Android050FlowTest.track(1,"hun"),Android050FlowTest.track(2,"eng")))));Library.Card card=new Library.Card(path,"Többnyelvű próba",true);f.setup(n,List.of(card));f.device.executeShellCommand("pm grant "+f.pkg+" android.permission.POST_NOTIFICATIONS");java.util.concurrent.atomic.AtomicReference<Intent> launched=new java.util.concurrent.atomic.AtomicReference<>();android.app.Instrumentation.ActivityMonitor monitor=new android.app.Instrumentation.ActivityMonitor(){@Override public android.app.Instrumentation.ActivityResult onStartActivity(Intent intent){if(Intent.ACTION_VIEW.equals(intent.getAction())){launched.set(new Intent(intent));return new android.app.Instrumentation.ActivityResult(android.app.Activity.RESULT_CANCELED,null);}return null;}};f.instrumentation.addMonitor(monitor);try{assertTrue(f.device.wait(Until.hasObject(By.desc(card.title)),10000));f.device.findObject(By.desc(card.title)).click();f.click("play_button");assertTrue(f.device.wait(Until.hasObject(By.text("Szám 1: hun (ac3)")),15000));f.text("Szám 1: hun (ac3)");long end=System.currentTimeMillis()+10000;while(launched.get()==null&&System.currentTimeMillis()<end)Thread.sleep(50);Intent view=launched.get();assertNotNull("External video intent",view);assertNull(view.getComponent());assertNull(view.getPackage());assertEquals(StreamService.mime(path),view.getType());assertEquals("http",view.getData().getScheme());Thread.sleep(400);assertNotNull(StreamService.readyUri);assertFalse(StreamService.audioPatch.isEmpty());assertFalse(f.device.hasObject(By.text("Lejátszó kiválasztása")));}finally{f.instrumentation.removeMonitor(monitor);}}}
}
